```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
	"reflect"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file_name> <struct_name>")
		os.Exit(1)
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	fileContent, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		fmt.Printf("Error reading file: %s\n", err.Error())
		return
	}

	parsedTree, err := parser.ParseFile(token.NewFileSet(), "", string(fileContent), parser.ParseComments|parser.ParseStruct)
	if err != nil {
		fmt.Printf("Error parsing file: %s\n", err.Error())
		return
	}

	ast.Inspect(parsedTree, func(node ast.Node) bool {
		switch node.(type) {
		case *ast.StructType:
			structNode := node.(*ast.StructType)
			structFields := make([]reflect.StructField, len(structNode.Fields))

			for i, field := range structNode.Fields {
				structFields[i] = reflect.StructField{
					Name:   field.Names[0].Text(),
					Type:   reflect.TypeOf(field.Type),
					Comment: field.Comment,
				}
			}

			structType := reflect.TypeOf(structName).Elem()
			avroSchema, _ := json.MarshalIndent(reflect.StructTag{}.New(structType, structFields), "", "  ")

			err := ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), []byte(avroSchema), 0644)
			if err != nil {
				fmt.Printf("Error writing Avro schema: %s\n", err.Error())
			} else {
				fmt.Printf("Avro schema generated successfully for struct: %s.avsc\n", structName)
			}

			return false
		default:
			return true
		}
	})
}
```

### Explanation:

- **Main Function**:
  - The `main` function checks if exactly two arguments (the source file name and the struct name) are provided.
  - It then reads the content of the source file and parses it into an AST using the `go/parser` package.

- **Parsing Structs**:
  - For each structure type found in the parsed tree, it extracts the fields.
  - It constructs a list of `reflect.StructField` based on these fields.
  - It compares this with the struct type being defined in the code and writes out an Avro schema corresponding to this struct.

### How to Use:

Save this code to a file, e.g., `script.go`, and execute it with your Go source file as an argument. Here's an example usage:

```sh
$ go run script.go test.go MyStruct
```

This will generate an Avro schema called `MyStruct.avsc` in the same directory as your Go source file.

Make sure you have the necessary packages installed (`go/ast`, `go/parser`) available when running this program.

